  for (const [b, t, P0] of zones){ const P = clean(P0); if (P.length < 3) continue; const Q = clean(offP(P, 1.0));
    prismP(B.p(GL), Q, Y(b), Y(t)); bandsP(B.p(LV), Q, Y(b) + 3.2, Y(t), 3.9, 0.35, 0.5);
    edgeP(B.p(ST), Q, Y(b), 0.8, 0.6, 0.3); }
  // the truss levels are enclosed too (double-height floors, recessed behind the trusses)
  for (const [b, t, P0] of zones){ if (b < 11 || b > 150) continue; const P = clean(P0); prismP(B.p({c:'#5f6c74', m:1, fh:3.9, cw:1.6}), clean(offP(P, 3.2)), Y(b - 8.2), Y(b), true); }
  // masts: four tubes each (to the OSM top), with the cross-links at every truss level
  const TR = [40, 75, 108, 135, 160];
