        const n = 4, du = (uB - uA)/n; for (let k = 0; k < n; k++){ const ua = uA + k*du, ub = ua + du; segP(o, P(ua, k % 2 ? y0 : y1), P(ub, k % 2 ? y1 : y0), 0.5, 4); }
