// a lawn / paving surface draped on the app ground over polygon P (cells of s m), skipping holes; returns the cell centres used
function drapeP(o, P, gf, s, skip, dy){
  const bb = bbP(P), used = [];
  for (let x = bb[0]; x < bb[2]; x += s) for (let z = bb[1]; z < bb[3]; z += s){ const cx = x + s/2, cz = z + s/2; if (!inPoly(P, cx, cz) || (skip && skip(cx, cz))) continue;
    const h = (a, b) => gf(a, b) + (dy || 0.15); quadP(o, [x, h(x, z), z], [x, h(x, z + s), z + s], [x + s, h(x + s, z + s), z + s], [x + s, h(x + s, z), z]); used.push([cx, cz]); }
  return used;
}
// ===== Cheung Kong Center (Cesar Pelli / Leo A Daly, 1999): 283 m, 63 storeys; a plain square prism (OSM ~47 m) clad in a fine
