  prismP(B.p({c:'#4f5c66', glow:'#ffe4bf', gk:0.6}), clean(offP(R0, 1.2)), Y(0), Y(18), true);
  mullP(B.p(GD2), R0, Y(0), Y(18), 5.9, 0.9, 0.05, 0.7);
  edgeP(B.p(GD2), R0, Y(17.4), 1.4, 1.2, 0.3);
  prismP(B.p(GL), R0, Y(18.6), Y(HT));
  // the grid: verticals every 1.5 m (heavier every 6 m) and a horizontal at every floor (4.0 m)
  mullP(B.p(GD), R0, Y(18.6), Y(HT - 0.5), 1.48, 0.14, 0.06, 0);
  mullP(B.p(GD), R0, Y(18.6), Y(HT - 0.5), 5.92, 0.32, 0.06, 0.3);
  bandsP(B.p(GD), R0, Y(22.6), Y(HT - 2), 4.0, 0.28, 0.08);
